import std.bytes (ByteArray)
import std.env
import std.io (Buffer, LimitReader, Read)
import std.json (Json)
import std.map (Map)
import std.net.http (Header, Response)
import std.net.http.client (Client)
import std.stdio (Stderr, Stdout, Stdin)
import std.string (StringBuffer, ToString)
import std.uri (Uri)

let MAX_OUTPUT_TOKENS = 128000
let THINKING_BUDGET_TOKENS = 100000
let MAX_INPUT_BYTES = 10  1024  1024
let MAX_RESPONSE_BYTES = 10  1024  1024
let DEFAULT_MODEL_ID = 'anthropic.claudeopus4720260101'
let DEFAULT_REGION = 'useast1'
let ANTHROPIC_VERSION = 'bedrock20230531'

fn required_env(name: String) > Result[String, String] {
  match env.get(name) {
    case Ok(value) if value.trim.size > 0 > Result.Ok(value.trim)
    case Ok(_) > Result.Error('The environment variable ${name} is empty')
    case Error(_) > Result.Error('The environment variable ${name} is missing')
  }
}

fn optional_env(name: String, fallback: String) > String {
  match env.get(name) {
    case Ok(value) if value.trim.size > 0 > value.trim
    case _ > fallback
  }
}

fn parse_uri(url: String, label: String) > Result[Uri, String] {
  match Uri.parse(url) {
    case Ok(uri) > Result.Ok(uri)
    case Error(error) > Result.Error('The ${label} is invalid: ${error}')
  }
}

fn read_string_limited[R: mut + Read[E], E: ToString](
  reader: mut R,
  label: String,
  limit: Int,
) > Result[String, String] {
  let bytes = ByteArray.new
  let limited = LimitReader.new(reader, limit + 1)

  match limited.read_all(bytes) {
    case Ok(_) > {
      if bytes.size > limit {
        Result.Error('The ${label} exceeds the maximum allowed size of ${limit} bytes')
      } else {
        Result.Ok(bytes.into_string)
      }
    }
    case Error(error) > Result.Error('Failed to read the ${label}: ${error.to_string}')
  }
}

fn read_response_body(response: Response, label: String) > Result[String, String] {
  read_string_limited(response.body, label, MAX_RESPONSE_BYTES)
}

fn parse_json_string(text: String, label: String) > Result[Json, String] {
  match Json.parse(Buffer.new(text)) {
    case Ok(json) > Result.Ok(json)
    case Error(error) > Result.Error('Failed to parse the ${label} as JSON: ${error}')
  }
}

fn validate_messages_input(input_json: String) > Result[Json, String] {
  let json = try parse_json_string(input_json, 'input payload')

  match json {
    case Json.Array(_) > Result.Ok(json)
    case _ > Result.Error('The input payload must be a JSON array of chat messages')
  }
}

fn error_message_from_body(body: String) > String {
  match parse_json_string(body.clone, 'error response body') {
    case Ok(json) > {
      match json.query.key('message').as_string {
        case Some(message) if message.size > 0 > message
        case _ > {
          match json.query.key('error').key('message').as_string {
            case Some(message) if message.size > 0 > message
            case _ > {
              match json.query.key('error_description').as_string {
                case Some(message) if message.size > 0 > message
                case _ > {
                  match json.query.key('error').as_string {
                    case Some(message) if message.size > 0 > message
                    case _ > body
                  }
                }
              }
            }
          }
        }
      }
    }
    case Error(_) > body
  }
}

fn normalize_messages(input: ref Json) > Json {
  match input {
    case Json.Array(items) > {
      let normalized = Array.new

      for item in items {
        match item {
          case Json.Object(object) > {
            let new_obj = Map.new

            match object.get('role') {
              case Ok(role) > new_obj.set('role', role.clone)
              case Error(_) > {}
            }

            match object.get('content') {
              case Ok(content) > {
                match content {
                  case Json.String(text) > {
                    let content_arr = Array.new
                    let content_obj = Map.new
                    content_obj.set('type', Json.String('text'))
                    content_obj.set('text', Json.String(text))
                    content_arr.push(Json.Object(content_obj))
                    new_obj.set('content', Json.Array(content_arr))
                  }
                  case Json.Array(_) > new_obj.set('content', content.clone)
                  case _ > new_obj.set('content', content.clone)
                }
              }
              case Error(_) > {}
            }

            normalized.push(Json.Object(new_obj))
          }
          case _ > {}
        }
      }

      Json.Array(normalized)
    }
    case _ > input.clone
  }
}

fn build_bedrock_invoke_body(
  input_json: String,
  max_output_tokens: Int,
  thinking_budget_tokens: Int,
) > Result[String, String] {
  let input = try validate_messages_input(input_json)
  let normalized_messages = normalize_messages(input)

  let root = Map.new
  root.set('anthropic_version', Json.String(ANTHROPIC_VERSION))
  root.set('max_tokens', Json.Int(max_output_tokens))

  let thinking_obj = Map.new
  thinking_obj.set('type', Json.String('enabled'))
  thinking_obj.set('budget_tokens', Json.Int(thinking_budget_tokens))
  root.set('thinking', Json.Object(thinking_obj))

  root.set('messages', normalized_messages)

  Result.Ok(Json.Object(root).to_string)
}

fn extract_text_from_content(content_array: ref Json, buffer: mut StringBuffer) {
  match content_array {
    case Json.Array(items) > {
      for item in items {
        match item {
          case Json.Object(object) > {
            match object.get('type') {
              case Ok(type_val) > {
                match type_val {
                  case Json.String(type_str) if type_str == 'text' > {
                    match object.get('text') {
                      case Ok(text_val) > {
                        match text_val {
                          case Json.String(text) if text.size > 0 > {
                            buffer.push(text)
                          }
                          case _ > {}
                        }
                      }
                      case Error(_) > {}
                    }
                  }
                  case _ > {}
                }
              }
              case Error(_) > {}
            }
          }
          case _ > {}
        }
      }
    }
    case _ > {}
  }
}

fn extract_output_text(body: String) > Result[String, String] {
  let json = try parse_json_string(body, 'Bedrock invoke response')

  match json {
    case Json.Object(object) > {
      match object.get('content') {
        case Ok(content) > {
          let buffer = StringBuffer.new
          extract_text_from_content(content, buffer)
          let text = buffer.into_string

          if text.size > 0 {
            Result.Ok(text)
          } else {
            match object.get('error') {
              case Ok(error_val) > {
                match error_val {
                  case Json.Object(err_obj) > {
                    match err_obj.get('message') {
                      case Ok(msg) > {
                        match msg {
                          case Json.String(message) > Result.Error('Bedrock error: ${message}')
                          case _ > Result.Error('Bedrock returned an error with no message')
                        }
                      }
                      case Error(_) > Result.Error('Bedrock returned an error with no message')
                    }
                  }
                  case _ > Result.Error('No text content in Bedrock response')
                }
              }
              case Error(_) > Result.Error('No text content found in Bedrock response')
            }
          }
        }
        case Error(_) > {
          match object.get('message') {
            case Ok(msg_val) > {
              match msg_val {
                case Json.String(message) > Result.Error('Bedrock API error: ${message}')
                case _ > Result.Error('Bedrock response missing content field')
              }
            }
            case Error(_) > Result.Error('Bedrock response missing content field')
          }
        }
      }
    }
    case _ > Result.Error('Bedrock response is not a JSON object')
  }
}

type BedrockClaudeClient {
  let @region: String
  let @api_key: String
  let @model_id: String

  fn static new(region: String, api_key: String, model_id: String) > Self {
    Self(
      region: region,
      api_key: api_key,
      model_id: model_id,
    )
  }

  fn invoke(input_json: String, max_output_tokens: Int, thinking_budget_tokens: Int) > Result[String, String] {
    let body = try build_bedrock_invoke_body(input_json, max_output_tokens, thinking_budget_tokens)
    let url = ''
    let uri = try parse_uri(url, label: 'Bedrock invoke endpoint')
    let client = Client.new

    let response = match client
      .post(uri)
      .header(Header.new('accept'), 'application/json')
      .header(Header.new('contenttype'), 'application/json')
      .header(Header.new('authorization'), 'Bearer ${@api_key}')
      .body(body) {
      case Ok(value) > value
      case Error(error) > {
        return Result.Error('Bedrock request failed: ${error}')
      }
    }

    let status = response.status.to_int
    let response_body = try read_response_body(response, 'Bedrock invoke response body')

    if status < 200 or status >= 300 {
      return Result.Error(
        'HTTP ${status}: ${error_message_from_body(response_body)}',
      )
    }

    extract_output_text(response_body)
  }
}

type async Main {
  fn async main {
    let stdout = Stdout.new
    let stderr = Stderr.new

    let input_json = match read_string_limited(Stdin.new, 'stdin input', MAX_INPUT_BYTES) {
      case Ok(value) > value
      case Error(error) > {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
        return
      }
    }

    let api_key = match required_env('BEDROCK_API_KEY') {
      case Ok(value) > value
      case Error(error) > {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
        return
      }
    }

    let region = optional_env('BEDROCK_REGION', DEFAULT_REGION)
    let model_id = optional_env('BEDROCK_MODEL_ID', DEFAULT_MODEL_ID)
    let client = BedrockClaudeClient.new(region, api_key, model_id)

    match client.invoke(input_json, MAX_OUTPUT_TOKENS, THINKING_BUDGET_TOKENS) {
      case Ok(output_text) > {
        let _ = stdout.write(output_text)
        let _ = stdout.flush
      }
      case Error(error) > {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
      }
    }
  }
}
